import{c as t,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"PairReduceSum","description":"","frontmatter":{},"headers":[{"level":1,"title":"PairReduceSum","slug":"pairreducesum"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/归约计算/PairReduceSum.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/归约计算/PairReduceSum.md"}'),l={name:"api/SIMD-API/基础API/Memory矢量计算/归约计算/PairReduceSum.md"};function p(i,a,d,r,c,o){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="pairreducesum" tabindex="-1">PairReduceSum <a class="header-anchor" href="#pairreducesum" aria-label="Permalink to &quot;PairReduceSum&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>PairReduceSum：相邻两个（奇偶）元素求和，例如（a1, a2, a3, a4, a5, a6...），相邻两个数据求和为（a1+a2, a3+a4, a5+a6, ......）。归约指令的总体介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/guide/%E7%BC%96%E7%A8%8B%E6%8C%87%E5%8D%97/%E7%B1%BB%E5%BA%93API/%E5%9F%BA%E7%A1%80API/%E5%B8%B8%E7%94%A8%E6%93%8D%E4%BD%9C%E9%80%9F%E6%9F%A5%E6%8C%87%E5%AF%BC/%E5%A6%82%E4%BD%95%E4%BD%BF%E7%94%A8%E5%BD%92%E7%BA%A6%E8%AE%A1%E7%AE%97API.md" target="_blank" rel="noreferrer">如何使用归约计算API</a>。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void PairReduceSum(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const int32_t repeatTime, const uint64_t mask[], const int32_t dstRepStride, const int32_t srcBlkStride, const int32_t srcRepStride)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void PairReduceSum(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const int32_t repeatTime, const int32_t mask, const int32_t dstRepStride, const int32_t srcBlkStride, const int32_t srcRepStride)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：half/float Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half/float Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half/float Atlas 200I/500 A2 推理产品，支持的数据类型为：half/float Atlas 推理系列产品AI Core，支持的数据类型为：half/float Atlas 训练系列产品，支持的数据类型为：half</td></tr><tr><td>isSetMask</td><td>是否在接口内部设置mask。 true，表示在接口内部设置mask。false，表示在接口外部设置mask，开发者需要使用SetVectorMask接口设置mask值。这种模式下，接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>repeatTime</td><td>输入</td><td>迭代次数。取值范围为[0, 255]。 关于该参数的具体描述请参考高维切分API。</td></tr><tr><td>mask/mask[]</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。 mask为数组形式，数组长度和数组元素的取值范围和操作数的数据类型有关。当操作数为16位时，数组长度为2，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，数组长度为1，mask[0]∈(0, 264-1]；当操作数为64位时，数组长度为1，mask[0]∈(0, 232-1]。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。</td></tr><tr><td>dstRepStride</td><td>输入</td><td>目的操作数相邻迭代间的地址步长。以一个repeat归约后的长度为单位。PairReduce完成后，一个repeat的长度减半。即单位为128Byte。 注意，此参数值Atlas 训练系列产品不支持配置0。</td></tr><tr><td>srcBlkStride</td><td>输入</td><td>单次迭代内datablock的地址步长。详细说明请参考dataBlockStride。</td></tr><tr><td>srcRepStride</td><td>输入</td><td>源操作数相邻迭代间的地址步长，即源操作数每次迭代跳过的datablock数目。详细说明请参考repeatStride。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>如果两两相加的两个元素mask位未配置（即当前两个元素不参与运算），对于Atlas 200I/500 A2 推理产品，对应的目的操作数中的值会置为0，对于其他产品型号，对应的目的操作数中的值不会变化。比如float场景下对64个数使用当前指令，mask配置为62，表示最后两个元素不参与运算，对于Atlas 200I/500 A2 推理产品，目的操作数中最后一个值会返回0；对于其他产品型号，目的操作数中最后一个值不会变化。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本样例中只展示Compute流程中的部分代码。完整样例可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/02_memory_vector_compute/pair_reduce_sum" target="_blank" rel="noreferrer">PairReduceSum样例</a>。</p><ul><li><p>PairReduceSum-tensor高维切分计算样例-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 设定mask为最多的128个全部元素参与计算</span></span>
<span class="line"><span>int32_t mask = 256/sizeof(half);</span></span>
<span class="line"><span>// 每个repeat128个元素，一共128个元素。</span></span>
<span class="line"><span>int repeat = 1;</span></span>
<span class="line"><span>// dstLocal: 目的操作数tensor</span></span>
<span class="line"><span>// srcLocal: 源操作数tensor</span></span>
<span class="line"><span>// srcBlkStride = 1, 在一个repeat中，block间没有空隙。</span></span>
<span class="line"><span>// dstRepStride = 1, srcRepStride = 8, repeat间没有空隙。</span></span>
<span class="line"><span>AscendC::PairReduceSum&lt;half&gt;(dstLocal, srcLocal, repeat, mask, 1, 1, 8);</span></span></code></pre></div></li><li><p>PairReduceSum-tensor高维切分计算样例-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 设定mask为最多的128个全部元素参与计算</span></span>
<span class="line"><span>uint64_t mask[2] = { UINT64_MAX, UINT64_MAX };</span></span>
<span class="line"><span>// 每个repeat128个元素，一共128个元素。</span></span>
<span class="line"><span>int repeat = 1;</span></span>
<span class="line"><span>// dstLocal: 目的操作数tensor</span></span>
<span class="line"><span>// srcLocal: 源操作数tensor</span></span>
<span class="line"><span>// srcBlkStride = 1, 在一个repeat中，block间没有空隙。</span></span>
<span class="line"><span>// dstRepStride = 1, srcRepStride = 8, repeat间没有空隙。</span></span>
<span class="line"><span>AscendC::PairReduceSum&lt;half&gt;(dstLocal, srcLocal, repeat, mask, 1, 1, 8);</span></span></code></pre></div></li><li><p>示例结果</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据src_gm：</span></span>
<span class="line"><span>[1, 1, 1, -1, 2, 2, -1, 2, </span></span>
<span class="line"><span> 3, 3, 3, -1, 4, 4, -2, 4,</span></span>
<span class="line"><span>....</span></span>
<span class="line"><span>]</span></span>
<span class="line"><span>输出数据dst_gm：</span></span>
<span class="line"><span>[2, 0, 4, 1, 6, 2, 8, 2, </span></span>
<span class="line"><span>....</span></span>
<span class="line"><span>]</span></span></code></pre></div></li></ul>`,19)])])}const m=t(l,[["render",p]]);export{u as __pageData,m as default};
